use mockito :: { Mock , Server , ServerGuard } ; use regex :: Regex ; # [doc = " Normalize dynamic addresses in messages for testing/logging."] pub fn normalize_ports (input : String) -> String { use regex :: Regex ; let re_ip_port = Regex :: new (r"127\.0\.0\.1:\d+") . unwrap () ; let re_http = Regex :: new (r"http://127\.0\.0\.1:\d+") . unwrap () ; let normalized = re_http . replace_all (& input , "http://127.0.0.1:<port>") ; let normalized = re_ip_port . replace_all (& normalized , "127.0.0.1:<port>") ; normalized . to_string () }